/**
 * The web edition — improvement #78, the whole book since BOOK-SPEC decision #24.
 *
 * `site/book/**` and `sidebar.json` are both generated by `scripts/build-site.ts` and both
 * gitignored, and so is `site/bn/book/**` (#127). Nothing in this directory is hand-written
 * except this file, `index.md`, `bn/index.md` and
 * `building-this-book.md` (web only — `site/` is in EXCLUDED_DIRS, so no PDF or EPUB has it),
 * so the site cannot drift from the manuscript: it is rebuilt from it every time.
 *
 * It is served at www.salmanrahman.com/handbook/: the portfolio rewrites that path to this
 * site's own Vercel project, which redeploys on every push to main (`vercel.json`).
 */
import { fileURLToPath, URL } from "node:url";
import { defineConfig } from "vitepress";
import { withMermaid } from "vitepress-plugin-mermaid";
import sidebar from "./sidebar.json" with { type: "json" };

const BASE = "/handbook/";

const DESCRIPTION_BN =
  "The Senior Full Stack Handbook, অনলাইনে বিনামূল্যে: নয়টি part, ছাপায় ৯০৩ পাতা, আর Book 2: DSA " +
  "Patterns — প্রতিটি অধ্যায়, ৭৩৪টি Interview-এর প্রশ্ন আর শব্দকোষ।";

const DESCRIPTION =
  "The Senior Full Stack Handbook, free to read online: nine parts, 903 pages in print, and " +
  "Book 2: DSA Patterns — every chapter, 734 interview questions and the glossary.";

export default withMermaid(
  defineConfig({
    title: "The Senior Full Stack Handbook",
    base: BASE,
    cleanUrls: true,
    lastUpdated: true,

    head: [
      // The portfolio's SR mark — VitePress does not prefix `head` links with `base`, so the
      // path is written out. `sizes: "any"` goes on the SVG, as the portfolio has it: a
      // browser picks the icon marked "any", and the .ico is only the fallback for one that
      // cannot draw SVG. The portfolio's own favicon.ico is Next's default triangle, so this
      // one is rendered from icon.svg rather than copied.
      ["link", { rel: "icon", href: `${BASE}favicon.ico`, sizes: "16x16 32x32 48x48" }],
      ["link", { rel: "icon", type: "image/svg+xml", href: `${BASE}icon.svg`, sizes: "any" }],
      ["meta", { property: "og:title", content: "The Senior Full Stack Handbook" }],
      ["meta", { property: "og:description", content: DESCRIPTION }],
      ["meta", { name: "twitter:card", content: "summary_large_image" }],
      // The Bangla edition's face (#127), applied under :lang(bn) in reading.css.
      ["link", { rel: "preconnect", href: "https://fonts.googleapis.com" }],
      ["link", { rel: "preconnect", href: "https://fonts.gstatic.com", crossorigin: "" }],
      [
        "link",
        {
          rel: "stylesheet",
          href: "https://fonts.googleapis.com/css2?family=Noto+Sans+Bengali:wght@400..700&display=swap",
        },
      ],
    ],

    // VitePress wants the base inside the hostname, or every sitemap URL drops /handbook.
    sitemap: { hostname: `https://www.salmanrahman.com${BASE}` },

    // The Bangla edition (#127) lives under /bn/. Every page exists in both, so the language
    // menu always lands on the same page; an untranslated one carries the English with a notice.
    locales: {
      root: {
        label: "English",
        lang: "en-GB",
        description: DESCRIPTION,
        themeConfig: {
          nav: [
            { text: "Read", link: "/book/front/preface" },
            { text: "Contents", link: "/book/" },
            { text: "Questions", link: "/book/back/interview-question-index" },
            { text: "Glossary", link: "/book/back/glossary" },
            { text: "How it's built", link: "/building-this-book" },
            { text: "salmanrahman.com", link: "https://www.salmanrahman.com/" },
          ],
          footer: {
            message: "The whole book, free to read. Generated from the manuscript on every change.",
            copyright: "© Salman Rahman",
          },
        },
      },
      bn: {
        label: "বাংলা",
        lang: "bn-BD",
        link: "/bn/",
        description: DESCRIPTION_BN,
        themeConfig: {
          nav: [
            { text: "পড়ুন", link: "/bn/book/front/preface" },
            { text: "সূচিপত্র", link: "/bn/book/" },
            { text: "প্রশ্ন", link: "/bn/book/back/interview-question-index" },
            { text: "শব্দকোষ", link: "/bn/book/back/glossary" },
            { text: "salmanrahman.com", link: "https://www.salmanrahman.com/" },
          ],
          footer: {
            message: "পুরো বই, বিনামূল্যে। প্রতিটি পরিবর্তনে পাণ্ডুলিপি থেকে নতুন করে তৈরি।",
            copyright: "© Salman Rahman",
          },
          outline: { level: [2, 3], label: "এই পাতায়" },
          docFooter: { prev: "আগের পাতা", next: "পরের পাতা" },
          lastUpdated: { text: "সর্বশেষ হালনাগাদ" },
          returnToTopLabel: "ওপরে ফিরে যান",
          sidebarMenuLabel: "মেনু",
          darkModeSwitchLabel: "থিম",
          lightModeSwitchTitle: "লাইট মোডে যান",
          darkModeSwitchTitle: "ডার্ক মোডে যান",
          langMenuLabel: "ভাষা বদলান",
          skipToContentLabel: "মূল লেখায় যান",
          notFound: {
            title: "পাতাটি পাওয়া যায়নি",
            quote: "এই ঠিকানায় কোনো পাতা নেই।",
            linkText: "প্রথম পাতায় ফিরুন",
          },
        },
      },
    },

    themeConfig: {
      sidebar: { "/book/": sidebar.en, "/bn/book/": sidebar.bn },

      outline: [2, 3],
      search: {
        provider: "local",
        options: {
          locales: {
            bn: {
              translations: {
                button: { buttonText: "খুঁজুন", buttonAriaLabel: "খুঁজুন" },
                modal: {
                  displayDetails: "বিস্তারিত দেখান",
                  resetButtonTitle: "মুছে ফেলুন",
                  backButtonTitle: "বন্ধ করুন",
                  noResultsText: "কিছু পাওয়া যায়নি",
                  footer: {
                    selectText: "বেছে নিন",
                    navigateText: "সরান",
                    closeText: "বন্ধ করুন",
                  },
                },
              },
            },
          },
        },
      },

      editLink: undefined,
    },

    ignoreDeadLinks: false,

    // The sidebar's reading-progress checkboxes: VitePress's own sidebar item, swapped for a
    // copy that carries one. Re-diff the copy on every VitePress upgrade.
    vite: {
      resolve: {
        alias: [
          {
            find: /^.*\/VPSidebarItem\.vue$/,
            replacement: fileURLToPath(new URL("./theme/ProgressSidebarItem.vue", import.meta.url)),
          },
        ],
      },
      // vitepress-plugin-mermaid pre-bundles mermaid's dependencies by bare name, which pnpm
      // does not hoist, so in dev the browser was handed CommonJS dayjs and fastdom and the
      // whole app failed to mount. Pre-bundling mermaid itself converts all of them at once.
      // The production build is unaffected.
      optimizeDeps: {
        include: ["mermaid"],
      },
      // `vitepress dev` cannot run api/progress.ts, so in development the API is forwarded to
      // `vercel dev` on its default port. Production never sees this — the function is served
      // alongside the static build there.
      server: {
        proxy: {
          [`${BASE}api`]: {
            target: "http://localhost:3000",
            rewrite: (path: string) => path.slice(BASE.length - 1),
          },
        },
      },
    },
  }),
);
